 label.querySelector('select').onchange=e=>{const next=enterpriseConfig.find(c=>c.id===e.target.value);if(!next||next.id===enterprise.id)return;if(manualModel&&(next.inline||enterprise.inline)){selectManualEnterprise(next);return;}const url=enterpriseEntry(next);url.hash='products';location.assign(url.href);};
