const usageScenes=[
 {id:'surveying',name:'测量测绘与定位',products:['gnss','survey']},
 {id:'farming',name:'农业作业与流体控制',products:['agriculture','fluid']},
 {id:'construction',name:'施工机械作业',products:['engineering']},
 {id:'water',name:'水域探测与船舶作业',products:['marine']},
 {id:'flight',name:'飞行平台运行',products:['drone']},
 {id:'environment',name:'形变与环境连续监测',products:['monitoring']},
 {id:'management',name:'行业信息采集与管理',products:['industry']},
 {id:'support',name:'跨场景配套与测试',products:['communication','power','mechanical','computing','testing','terminal']},
 {id:'uncertain',name:'用途待核实',products:['other']}
];
let lawFilter={status:'',region:'',stage:''};
const lawNames={'manual-pending':'人工记录：申请中','manual-granted':'人工记录：授权（有效性待核实）','manual-active':'人工记录：有效（见核验方式）','manual-terminated':'人工记录：终止','manual-expired':'人工记录：届满','manual-invalid':'人工记录：无效','manual-unknown':'人工记录：待核实','manual-conflict':'人工记录冲突','source-active':'有效（来源快照）','source-inactive':'失效（来源快照）','source-pending':'审中（来源快照）',unverified:'无可用状态快照'};
let statusSnapshot=null,statusRecords=new Map(),statusSnapshotIssue='';
function validateStatusSnapshot(data,baseline){
 const rootKeys=['schemaVersion','source','snapshotDate','officialVerified','verificationLabel','records'];
 if(!data||Object.keys(data).sort().join()!==rootKeys.sort().join()||data.schemaVersion!==1||data.source!=='IncoPat'||data.officialVerified!==false||data.verificationLabel!=='第三方数据库快照，未官方核验'||!/^\d{4}-\d{2}-\d{2}$/.test(data.snapshotDate)||!Array.isArray(data.records))throw Error('Invalid status snapshot');
 const base=new Map(baseline.map(d=>[d.id,d.applicationNumber])),seen=new Map(),apps=new Map();
 for(const r of data.records){if(Object.keys(r).sort().join()!==['applicationNumber','jurisdiction','publicationId','statusRaw','validityRaw'].join()||!base.has(r.publicationId)||base.get(r.publicationId)!==r.applicationNumber||seen.has(r.publicationId)||r.jurisdiction!=='CN'||![r.statusRaw,r.validityRaw].every(x=>typeof x==='string'&&x.trim()&&x.length<80))throw Error('Status record mismatch');const value=JSON.stringify([r.statusRaw,r.validityRaw,r.jurisdiction]);if(apps.has(r.applicationNumber)&&apps.get(r.applicationNumber)!==value)throw Error('Conflicting application states');apps.set(r.applicationNumber,value);seen.set(r.publicationId,r);}
 return seen;
}
async function loadStatusSnapshot(){try{const response=await fetch('data/incopat-status-snapshot.json');if(!response.ok)throw Error('Unavailable status snapshot');const data=await response.json();const validated=validateStatusSnapshot(data,currentDocs);statusSnapshot=data;statusRecords=validated;}catch(e){statusSnapshot=null;statusRecords=new Map();statusSnapshotIssue='状态快照未能载入或关联校验失败；当前仅保留原始资料，不能解释为无变化。';}}
function sourceStatus(d){const r=statusRecords.get(d.id);return r&&r.applicationNumber===d.applicationNumber?r:null;}
function sourceStatusText(d){const m=manualStatus(d);if(m&&!m.stale)return `${m.event.record.statusRaw} · ${m.event.record.asOf} · ${m.conflict?'存在冲突':'人工提交，见依据'}`;const r=sourceStatus(d);return r?`${r.statusRaw} / ${r.validityRaw} · IncoPat ${statusSnapshot.snapshotDate} · 未官方核验`:'无可用状态快照 · 待核实';}
function statusOverview(ds){const counts=Object.entries(lawNames).map(([id,label])=>{const rows=ds.filter(d=>patentLaw(d).status===id);return rows.length?`<li>${esc(label)}：${rows.length} 文献 / ${new Set(rows.map(d=>d.applicationNumber)).size} 申请</li>`:'';}).join('');return `<details class="source-status-summary" open><summary>状态快照 · 当前匹配</summary><p>${statusSnapshot?'IncoPat · '+esc(statusSnapshot.snapshotDate)+' · 第三方记录，非实时状态；未官方核验。':esc(statusSnapshotIssue||'尚无状态快照')}</p><ul>${counts}</ul><p>按申请号去重；公布与授权版本仍分别保留。来源“有效”不等于已官方核实有效地域。</p></details>`;}
function patentLaw(d){
 const observation=sourceStatus(d),manual=manualStatus(d);
 const prefix=(d.id||'').match(/^[A-Z]{2}/)?.[0]||'',labels={CN:'中国',WO:'PCT国际公布（非授权地域）',EP:'欧洲专利局程序（非全欧洲有效）',US:'美国',JP:'日本',KR:'韩国'};
 const region=labels[prefix]||d.country||'地域待核实';
 const conflict=prefix==='CN'&&d.country&&d.country!=='中国';
 const grant=prefix==='CN'&&(/[BUS]$/.test(d.id)||d.patentType==='发明授权');
 // A document kind is evidence of publication type, not current validity or national coverage.
 return {region:conflict?'地域冲突待核实':region,regionCode:conflict?'unknown':prefix||'unknown',stage:grant?'grant-document':(/A\d?$/.test(d.id)?'published':'unknown'),status:manual&&!manual.conflict&&!manual.stale?('manual-'+manual.event.record.normalizedStatus):manual?.conflict?'manual-conflict':observation?({'有效':'source-active','失效':'source-inactive','审中':'source-pending'}[observation.validityRaw]||'unverified'):'unverified',observation,rawStatus:d.legalStatus||'未提供',patentType:/^发明/.test(d.patentType||'')?'发明':d.patentType||'待核实',grantDocument:grant?d.id:null,verifiedGrantRegions:[],verifiedActiveRegions:[],eventDate:null,collectedDate:d.providedEvidenceDate||null,verifiedAt:null,source:d.googlePatentsUrl||d.sourceUrl||null,snapshot:byClaim[d.id]?.statusSnapshot||null};
}
function lawMatches(d){const l=patentLaw(d);return (!lawFilter.status||l.status===lawFilter.status)&&(!lawFilter.region||l.regionCode===lawFilter.region)&&(!lawFilter.stage||l.stage===lawFilter.stage)&&(!lawFilter.since||(manualStatus(d)?.event.enteredAt||'').slice(0,10)>=lawFilter.since)&&(!lawFilter.raw||l.observation?.statusRaw===lawFilter.raw);}
function lawBadge(d){const l=patentLaw(d),m=manualStatus(d);if(m)return `<span class="law-badge">${esc(d.id.slice(0,2))} · ${esc(m.event.record.statusRaw)} · 截至 ${esc(m.event.record.asOf)} · ${m.conflict?'存在冲突':m.stale?'较旧记录待核实':'人工提交记录（见依据）'}</span>`;return `<span class="law-badge">${esc(l.region)} · ${esc(l.patentType)} · ${esc(sourceStatusText(d))}</span>`;}
function lawDetails(d){const l=patentLaw(d),snap=l.snapshot;return `<section class="law-panel"><h2>法律状态与地域</h2><p class="law-warning">${l.observation?'IncoPat 第三方快照，非实时状态；未官方核验。来源“有效”不是官方法律结论。':'无可用状态快照，当前状态待核实。'}${l.grantDocument?'已有授权公告文献不代表当前仍有效。':''}方法／结构／外观是本站技术内容分类，法定专利类型另列。</p><dl><dt>申请号</dt><dd>${esc(d.applicationNumber||'未提供')}</dd><dt>完整公开号／公告号</dt><dd>${esc(d.id)}</dd><dt>授权公告号</dt><dd>${esc(l.grantDocument||'本记录未确认')}</dd><dt>法定专利类型</dt><dd>${esc(l.patentType)}</dd><dt>文献阶段</dt><dd>${l.stage==='grant-document'?'授权公告文献（由中国文献标识识别）':l.stage==='published'?'已公开的申请文献，不推断目前仍在审查':'待核实'}</dd><dt>来源当前法律状态（快照）</dt><dd>${esc(l.observation?.statusRaw||'未取得')}</dd><dt>来源专利有效性（快照）</dt><dd>${esc(l.observation?.validityRaw||'未取得')} · 未官方核验</dd><dt>状态来源／快照日期</dt><dd>${l.observation?'IncoPat / '+esc(statusSnapshot.snapshotDate)+'（不是法律事件日期或官方核验日期）':'未取得'}</dd><dt>原资料基线状态（保留）</dt><dd>${esc(l.rawStatus)}</dd><dt>申请／公布地域</dt><dd>${esc(l.region)}（依文献标识及原始地域字段）</dd><dt>已核实授权地域</dt><dd>未核实</dd><dt>已核实有效地域</dt><dd>未核实</dd><dt>申请日／文献公开日</dt><dd>${esc(d.filingDate||'未提供')} / ${esc(d.pubDate||'未提供')}（不是当前法律事件日期）</dd><dt>状态事件日期</dt><dd>未提供</dd><dt>来源资料日期</dt><dd>${esc(l.collectedDate||'未提供')}（上传资料标注）</dd><dt>逐条数据采集日期</dt><dd>未提供</dd><dt>实际官方核验日期</dt><dd>尚未核验</dd></dl>${snap?`<details><summary>其他第三方历史线索（独立保留，不覆盖 IncoPat 快照）</summary><p>不同来源、日期与状态词可能不同；不将它们自动合并或判定为状态变化。存在差异时须查官方登记。</p><p>${esc(snap.provider||'第三方')}：${esc(snap.displayedStatus||'未提供')}；历史页面查阅日期 ${esc(snap.checkedAt||'未提供')}，非法律事件日期。${/^https:\/\//.test(snap.sourceUrl||'')?`<a href="${esc(snap.sourceUrl)}" target="_blank" rel="noopener">原线索来源</a>`:''}</p></details>`:''}<p>${l.observation?'<a href="https://www.incopat.com/" target="_blank" rel="noopener">IncoPat 来源平台 ↗</a>（平台入口，非逐条官方登记） · ':''}${l.source&&/^https:\/\//.test(l.source)?`<a href="${esc(l.source)}" target="_blank" rel="noopener">本条现有文献来源（第三方） ↗</a> · `:''}<a href="https://www.cnipa.gov.cn/" target="_blank" rel="noopener">国家知识产权局官方入口 ↗</a>（核验入口，不代表已查得本条登记）</p><p class="sub">未提供跨地域同族登记，不推断其他国家权利。<a href="https://www.wipo.int/en/web/pct-system/faqs/faqs" target="_blank" rel="noopener">PCT 国际申请须分别进入国家／地区程序</a>；<a href="https://www.epo.org/en/searching-for-patents/legal/register" target="_blank" rel="noopener">EP 授权后地域状态须查对应登记</a>。本站不据导图作侵权或自由实施结论。</p></section>`;}
