function patentNodePoint(d,state={}){
 const a=currentAnalyses.find(x=>x.id===d.id);
 const refs=routeData.assignments.filter(r=>r.analysisId===d.id&&r.subpathId===state.topic&&r.form===state.form);
 const groups=refs.map(r=>a?.formGroups?.[r.formGroupIndex]).filter(Boolean);
 const g=groups.find(g=>g.label)||a?.formGroups?.find(g=>g.label);
 if(g)return {title:g.label,description:currentStrings(g.summary).join('；'),claimNumbers:g.claimNumbers||g.evidenceClaimNumbers||[],basis:g.form==='design'?'本件外观资料解读':'本件已有技术分析',sourceId:d.id};
 const text=currentTexts[d.id],claim=text?.claims?.find(c=>Number(c.number)===1)||text?.claims?.[0];
 if(claim?.text){
  const raw=claim.text.replace(/\s+/g,' ').trim();
  let feature=raw.includes('其特征在于')?raw.split('其特征在于').slice(1).join('其特征在于'):raw;
  feature=feature.replace(/^[，,:：\s]+/,'').replace(/^所述方法(?:应用于[^；。]+[；。]|包括[：:]?)/,'').trim();
  if(feature.includes('所述方法包括：'))feature=feature.split('所述方法包括：').slice(1).join('所述方法包括：');
  feature=feature.replace(/^[，,:：\s]+/,'').trim();
  const clause=feature.split(/[；。]/).find(x=>x.trim().length>8)||feature;
  return {title:clause.trim(),description:raw,claimNumbers:[claim.number],basis:'本版本权项摘录（未新增范围分析）',sourceId:d.id,sourceUrl:text.sourceUrl};
 }
 return {title:a?.function||'技术要点依据待补充',description:'未取得足够的对应版本技术文本，不由名称或其他文献推断。',claimNumbers:[],basis:'待核实',sourceId:d.id};
}
function technicalPointEvidence(d){const point=patentNodePoint(d,panorama);return `<section class="technical-point-evidence"><h2>${d.patentType==='外观设计'?'外观资料要点':'技术要点'}</h2><p><b>${esc(point.title)}</b></p>${point.basis.includes('权项摘录')?`<details><summary>展开本版本权项原文依据</summary><p>${esc(point.description)}</p></details>`:`<p>${esc(point.description)}</p>`}<p class="sub">${esc(point.basis)} · 文献 ${esc(point.sourceId)}${point.claimNumbers.length?' · 权项 '+point.claimNumbers.map(esc).join('、'):''}。用于阅读定位，不单独认定新颖性或完整保护范围。</p></section>`;}
