 const count=docs=>`${new Set(docs.map(d=>d.applicationNumber)).size} 申请 · ${docs.length} 文献`;
 const productNode=p=>{const c=productCoverage(p.id,ds);return {id:p.id,title:p.name,sub:(activeResultFilters().length?'当前 ':'')+`${c.applications} 申请 · ${c.documents} 文献`,meta:c.reason==='filtered-empty'?`筛选无匹配 · 全库 ${c.totalApplications} 申请 / ${c.totalDocuments} 文献`:c.reason==='unpopulated'?'本企业尚无归属资料':activeResultFilters().length?`全库 ${c.totalApplications} 申请 / ${c.totalDocuments} 文献`:'',emptyReason:c.reason==='matched'?'':c.reason,coverage:c,description:p.include,action:{level:'product',product:p.id,form:'',path:'',topic:''}};};
 let counted=scoped;
