 groups=scenes.filter(s=>state.level==='overview'||s.id===state.scene).map((s,i)=>({id:s.id,title:s.name,color:['#496e9c','#429184','#ad8849','#6b7daa'][i%4],action:{level:'scene',scene:s.id,product:''},children:s.products.map(id=>primaryById[id]).filter(Boolean).map(productNode)}));
 if(state.level==='scene'){title=usageScenes.find(s=>s.id===state.scene)?.name||'用途待核实';nodes=groups.flatMap(g=>g.children);const ids=new Set(nodes.map(n=>n.id));counted=ds.filter(d=>ids.has(primaryMap[d.applicationNumber]?.primaryProductId));groups=[];}
