 if(at<0)return false;
 if(panorama.level==='topic'&&target.patent){const nodes=panoramaData(currentFiltered()).nodes,i=nodes.findIndex(n=>n.patent===target.patent);if(i>=0&&panorama.page!==Math.floor(i/12)){panorama.page=Math.floor(i/12);nodeDetail=null;currentRender();return true;}}
