 let active=null,deepest=-1;
 for(const b of buttons){
  b.classList.remove('guide-match','guide-active','guide-target','located');b.removeAttribute('aria-description');const tag=b.querySelector('.pm-guide-tag');tag.hidden=true;tag.textContent='';
  const key=b.dataset.guideKey,count=mapGuidance.matches.filter(m=>{const at=m.trail.findIndex(x=>x.key===currentKey);return at>=0&&m.trail.slice(at).some(x=>x.key===key);}).length;
  if(!count||(key===currentKey&&key!==target?.key))continue;
  const at=activeTrail.findIndex(x=>x.key===currentKey),pos=activeTrail.findIndex(x=>x.key===key),onPath=at>=0&&pos>=at,isTarget=target?.key===key;
  b.classList.add('guide-match');if(onPath)b.classList.add('guide-active');if(isTarget)b.classList.add('guide-target');
  const label=isTarget?'◎ 定位目标':onPath?'→ 沿此进入':'◇ 含匹配';tag.textContent=label+(count>1?' · '+count+' 项':'');tag.hidden=false;b.setAttribute('aria-description',tag.textContent);
  if(onPath&&pos>deepest){active=b;deepest=pos;}
 }
 if(active){active.classList.add('located');if(center){const nr=active.getBoundingClientRect(),vr=viewport.getBoundingClientRect();viewport.scrollLeft+=nr.left-vr.left-viewport.clientWidth/2+nr.width/2;viewport.scrollTop+=nr.top-vr.top-viewport.clientHeight/2+nr.height/2;savePanoramaView();}}
 const q=mapGuidance.query.trim(),outside=target&&!activeTrail.some(x=>x.key===currentKey),total=mapGuidance.matches.length;
 result.textContent=!q?'':!total?'无匹配节点；请更换名称或完整专利号。':`${mapGuidance.index+1} / ${total} 个匹配节点／路径 · ${target.title}${target.patent?' · '+target.patent:''}${outside?' · 目标位于其他分支，请返回检索起点':active?.classList.contains('guide-target')?' · 已到达目标，点击查看详情':' · 沿红框箭头逐级进入'}`;
