 document.querySelectorAll('[data-pm-go]').forEach(b=>b.onclick=()=>{const next=JSON.parse(b.dataset.pmGo),model=panoramaData(currentFiltered(),{...panorama,...next});if(b.closest('.pm-node')&&!model.groups.length&&!model.nodes.length){showNodeDetail({title:model.title,description:model.description,sub:model.count,coverage:next.product?productCoverage(next.product):null});}else panoramaGo(next);});
